// 1.14d: 00484e90
void INV_FormatDurabilityText(uint16_t * wszText, D2UnitStrc * pUnit) {
    uint16_t wszNumBuf[10];
    char szNumBuffer[12];
    wszNumBuf[0] = L'\0';
    wszNumBuf[1] = 0;
    wszNumBuf[2] = 0;
    wszNumBuf[3] = 0;
    wszNumBuf[4] = 0;
    wszNumBuf[5] = 0;
    wszNumBuf[6] = 0;
    wszNumBuf[7] = 0;
    wszNumBuf[8] = 0;
    wszNumBuf[9] = 0;
    uint16_t* pwColorPrefix = D2Lang::StrTable::strtable::GetLocaleString(0xf9b);
    uint16_t* pwDurabilitySuffix = D2Lang::StrTable::strtable::GetLocaleString(0xf9e);
    uint32_t bHasDurability = D2Common::ITEMS::Items::ITEM_CheckIfItemHasDurability(pUnit);
    if (!bHasDurability) {
      return;
    }

    int32_t nDurabilityBonus = D2Common::Stats::StatsEx::STATLIST_GetMaxDurabilityFromUnit(pUnit);
    if (nDurabilityBonus <= 0) {
      return;
    }

    int32_t bHasDurabilityBonus = D2Common::ITEMS::Items::ITEM_GetTxtItemTypes_throwable(pUnit);
    if (bHasDurabilityBonus) {
      return;
    }

    nDurabilityBonus = D2Common::Stats::StatsEx::STATLIST_GetStatBonusFromLists(pUnit, UNITSTAT_item_maxdurability_percent, 0);
    if (nDurabilityBonus) {
      bHasDurabilityBonus = 1;
    }

    uint16_t* pwLabelStr = D2Lang::StrTable::strtable::GetLocaleString(0xd81);
    D2Lang::Unicode::UNISYS::STRING_CopyWideString(wszText, pwLabelStr);
    int nCurDurability = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_durability, 0);
    Storm::Source::SSTR::SStrPrintf(szNumBuffer, 10, "%i", nCurDurability);
    D2Lang::Unicode::UNISYS::AppendToBuffer(wszText, pwColorPrefix);
    D2Lang::Unicode::UNISYS::STRING_CopyCharToWCharWithSetMaxSize(wszNumBuf, szNumBuffer, 9);
    D2Lang::Unicode::UNISYS::AppendToBuffer(wszText, wszNumBuf);
    D2Lang::Unicode::UNISYS::AppendToBuffer(wszText, pwColorPrefix);
    pwLabelStr = D2Lang::StrTable::strtable::GetLocaleString(0xd87);
    D2Lang::Unicode::UNISYS::AppendToBuffer(wszText, pwLabelStr);
    D2Lang::Unicode::UNISYS::AppendToBuffer(wszText, pwColorPrefix);
    nDurabilityBonus = D2Common::Stats::StatsEx::STATLIST_GetMaxDurabilityFromUnit(pUnit);
    Storm::Source::SSTR::SStrPrintf(szNumBuffer, 10, "%i", nDurabilityBonus);
    D2Lang::Unicode::UNISYS::STRING_CopyCharToWCharWithSetMaxSize(wszNumBuf, szNumBuffer, 9);
    if (bHasDurabilityBonus) {
      D2Client::UI::ui::AppendAsWideChar(wszNumBuf, 3);
    }

    D2Lang::Unicode::UNISYS::AppendToBuffer(wszText, wszNumBuf);
    D2Lang::Unicode::UNISYS::AppendToBuffer(wszText, pwDurabilitySuffix);
}
